import{_ as t}from"./chunks/figure-1.BTRsyKmP.js";import{_ as a}from"./chunks/figure-2.Uj5hNtKH.js";import{_ as n}from"./chunks/figure-2.C8-JOLrz.js";import{_ as i}from"./chunks/figure-6.B_uOYz7L.js";import{_ as o}from"./chunks/figure-3.kZ6zBeSW.js";import{_ as s}from"./chunks/figure-2.J0SR2L_b.js";import{_ as r}from"./chunks/figure-3.l2wjAzrc.js";import{_ as d}from"./chunks/figure-1.Dbyz5qZx.js";import{_ as c}from"./chunks/infinite_timeev.BbZnSoGY.js";import{_ as h}from"./chunks/figure-1.CYNrvglI.js";import{_ as l}from"./chunks/figure-1.CB4JCrzm.js";import{_ as m,o as g,c as p,ao as u}from"./chunks/framework.DA_3JxoV.js";const X=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md","lastUpdated":null}'),f={name:"examples/index.md"};function x(b,e,y,_,T,S){return g(),p("div",null,[...e[0]||(e[0]=[u('<h1 id="examples_index" tabindex="-1">Examples <a class="header-anchor" href="#examples_index" aria-label="Permalink to &quot;Examples {#examples_index}&quot;">​</a></h1><p>This gallery collects the full worked examples that ship with MPSKit.jl. Each one is a complete, runnable script (also available as a Jupyter notebook, linked from the example page itself) that goes well beyond the short snippets in the how-to guides.</p><p>The examples are grouped by the kind of computation they demonstrate rather than by the physical system. Within each group they are listed roughly in order of increasing difficulty: start at the top if you are new to MPSKit, and work down as you get comfortable with symmetries, infinite systems, and the less common algorithms.</p><h2 id="Ground-states" tabindex="-1">Ground states <a class="header-anchor" href="#Ground-states" aria-label="Permalink to &quot;Ground states {#Ground-states}&quot;">​</a></h2><h3 id="The-transverse-field-Ising-model:-a-complete-ground-state-studygroundstates/0.tfim-groundstate/index.md" tabindex="-1"><a href="./groundstates/0.tfim-groundstate/">The transverse-field Ising model: a complete ground-state study</a> <a class="header-anchor" href="#The-transverse-field-Ising-model:-a-complete-ground-state-studygroundstates/0.tfim-groundstate/index.md" aria-label="Permalink to &quot;[The transverse-field Ising model: a complete ground-state study](groundstates/0.tfim-groundstate/index.md) {#The-transverse-field-Ising-model:-a-complete-ground-state-studygroundstates/0.tfim-groundstate/index.md}&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>Assembles the tools from the tutorials into one case study of the TFIM phase transition: finite-ring <code>DMRG</code> versus infinite-chain <code>VUMPS</code> magnetization curves in a single figure, plus the entanglement entropy and correlation length of the infinite state across the transition. The natural first example after finishing the tutorial track. <strong>Level: introductory.</strong></p><h3 id="The-XXZ-modelgroundstates/1.xxz-heisenberg/index.md" tabindex="-1"><a href="./groundstates/1.xxz-heisenberg/">The XXZ model</a> <a class="header-anchor" href="#The-XXZ-modelgroundstates/1.xxz-heisenberg/index.md" aria-label="Permalink to &quot;[The XXZ model](groundstates/1.xxz-heisenberg/index.md) {#The-XXZ-modelgroundstates/1.xxz-heisenberg/index.md}&quot;">​</a></h3><p><img src="'+a+'" alt=""></p><p>Walks through a ground-state search that first goes wrong: single-site <code>VUMPS</code> and <code>GradientGrassmann</code> stall on the spin-1/2 Heisenberg antiferromagnet, and <code>transferplot</code>/<code>entanglementplot</code> reveal a near-non-injective state with several almost-degenerate transfer-matrix eigenvalues. The fix is a two-site unit cell together with the <code>SU2Irrep</code>-symmetric Hamiltonian, after which <code>IDMRG2</code> and <code>VUMPS</code> converge cleanly. A useful, diagnostic-driven example for recognizing and debugging convergence failures. <strong>Level: intermediate.</strong></p><h3 id="Hubbard-chain-at-half-fillinggroundstates/2.hubbard/index.md" tabindex="-1"><a href="./groundstates/2.hubbard/">Hubbard chain at half filling</a> <a class="header-anchor" href="#Hubbard-chain-at-half-fillinggroundstates/2.hubbard/index.md" aria-label="Permalink to &quot;[Hubbard chain at half filling](groundstates/2.hubbard/index.md) {#Hubbard-chain-at-half-fillinggroundstates/2.hubbard/index.md}&quot;">​</a></h3><p><img src="'+n+'" alt=""></p><p>Studies the 1D Hubbard model at half filling with fermionic <code>InfiniteMPS</code>, first benchmarking a plain <code>VUMPS</code>/<code>GradientGrassmann</code> ground-state search against the exact Bethe-ansatz integral for the energy, then imposing the full particle-number and spin symmetry (<code>U1Irrep</code>, <code>SU2Irrep</code>, with <code>MPSKit.add_physical_charge</code> to pin the filling) and constructing the spinon/holon excitation spectrum with the <code>QuasiparticleAnsatz</code>. Combines fermionic symmetry sectors with a more elaborate ground-state recipe (staged bond-dimension growth via <code>changebonds</code>/<code>OptimalExpand</code>, <code>SvdCut</code>, and mixed <code>VUMPS</code>/<code>GradientGrassmann</code> refinement). <strong>Level: advanced.</strong></p><h3 id="1D-Bose-Hubbard-modelgroundstates/3.bose-hubbard/index.md" tabindex="-1"><a href="./groundstates/3.bose-hubbard/">1D Bose-Hubbard model</a> <a class="header-anchor" href="#1D-Bose-Hubbard-modelgroundstates/3.bose-hubbard/index.md" aria-label="Permalink to &quot;[1D Bose-Hubbard model](groundstates/3.bose-hubbard/index.md) {#1D-Bose-Hubbard-modelgroundstates/3.bose-hubbard/index.md}&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>The most comprehensive ground-state example in the gallery: works directly in the thermodynamic limit with a truncated bosonic local Hilbert space, extracts correlation functions and the correlation length as a function of bond dimension, computes the momentum distribution, and maps out the Mott-insulator/superfluid structure of the phase diagram from the ground-state response to an applied phase twist. Touches most of the ground-state toolbox (<code>InfiniteMPS</code>, <code>find_groundstate</code>, bond-dimension control, <code>expectation_value</code>-based observables) in a single, longer study. <strong>Level: advanced.</strong></p><h3 id="Spin-1-Heisenberg-modelgroundstates/4.haldane-spt/index.md" tabindex="-1"><a href="./groundstates/4.haldane-spt/">Spin 1 Heisenberg model</a> <a class="header-anchor" href="#Spin-1-Heisenberg-modelgroundstates/4.haldane-spt/index.md" aria-label="Permalink to &quot;[Spin 1 Heisenberg model](groundstates/4.haldane-spt/index.md) {#Spin-1-Heisenberg-modelgroundstates/4.haldane-spt/index.md}&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>Distinguishes the two symmetry-protected topological phases of the SU(2)-symmetric spin-1 Heisenberg chain by restricting the virtual <code>SU2Space</code> to integer or half-integer charges, then compares the two resulting ground states through their energy, transfer-matrix spectrum (<code>transferplot</code>), entanglement spectrum (<code>entanglementplot</code>), and entanglement entropy (<code>entropy</code>). Builds directly on the symmetry machinery introduced in the Haldane gap example. <strong>Level: intermediate/advanced.</strong></p><h3 id="The-Ising-CFT-spectrumgroundstates/5.ising-cft/index.md" tabindex="-1"><a href="./groundstates/5.ising-cft/">The Ising CFT spectrum</a> <a class="header-anchor" href="#The-Ising-CFT-spectrumgroundstates/5.ising-cft/index.md" aria-label="Permalink to &quot;[The Ising CFT spectrum](groundstates/5.ising-cft/index.md) {#The-Ising-CFT-spectrumgroundstates/5.ising-cft/index.md}&quot;">​</a></h3><p><img src="'+s+'" alt=""></p><p>Extracts the finite-size conformal spectrum of the critical transverse-field Ising chain, first by brute-force <code>exact_diagonalization</code> on a small periodic chain, then by extending to larger sizes with finite <code>DMRG</code> and the <code>QuasiparticleAnsatz</code>, using a translation MPO to assign a momentum label to each state. No symmetries are used, which makes this a good entry point into the finite-MPS workflow. <strong>Level: introductory.</strong></p><h2 id="Excitations-and-dispersions" tabindex="-1">Excitations &amp; dispersions <a class="header-anchor" href="#Excitations-and-dispersions" aria-label="Permalink to &quot;Excitations &amp; dispersions {#Excitations-and-dispersions}&quot;">​</a></h2><h3 id="The-Haldane-gapexcitations/0.haldane/index.md" tabindex="-1"><a href="./excitations/0.haldane/">The Haldane gap</a> <a class="header-anchor" href="#The-Haldane-gapexcitations/0.haldane/index.md" aria-label="Permalink to &quot;[The Haldane gap](excitations/0.haldane/index.md) {#The-Haldane-gapexcitations/0.haldane/index.md}&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>Computes the Haldane gap of the spin-1 Heisenberg antiferromagnet in two complementary ways: finite-size <code>DMRG</code> with the <code>QuasiparticleAnsatz</code>, extrapolated over system size, and a direct infinite-chain <code>VUMPS</code> calculation with a momentum-resolved excitation scan. Introduces <code>SU2Irrep</code>/<code>SU2Space</code> symmetric tensors for both <code>FiniteMPS</code> and <code>InfiniteMPS</code>. <strong>Level: intermediate.</strong></p><h3 id="The-SU3-Heisenberg-chainexcitations/1.su3-heisenberg/index.md" tabindex="-1"><a href="./excitations/1.su3-heisenberg/">The SU(3) Heisenberg chain</a> <a class="header-anchor" href="#The-SU3-Heisenberg-chainexcitations/1.su3-heisenberg/index.md" aria-label="Permalink to &quot;[The SU(3) Heisenberg chain](excitations/1.su3-heisenberg/index.md) {#The-SU3-Heisenberg-chainexcitations/1.su3-heisenberg/index.md}&quot;">​</a></h3><p><img src="'+d+'" alt=""></p><p>Reproduces the setup of the SU(3) <code>[3 0 0]</code> Heisenberg chain (<a href="/MPSKit.jl/previews/PR449/references#devos2022">Devos <em>et al.</em>, 2022</a>): the physical site carries the ten-dimensional <code>[3 0 0]</code> irrep, the SU(3)-invariant nearest-neighbour coupling is assembled by hand with <a href="https://github.com/QuantumKitHub/SUNRepresentations.jl" target="_blank" rel="noreferrer">SUNRepresentations.jl</a> (MPSKitModels has no built-in SU(N) Heisenberg), the uniform ground state is found with <code>VUMPS</code>, and the <code>[2 1 0]</code>-sector excitation dispersion is scanned across the Brillouin zone. The natural non-abelian counterpart to the spin-1 Haldane gap example, and the only gallery example using an SU(N&gt;2) symmetry. <strong>Level: advanced.</strong></p><h2 id="Dynamics-and-finite-temperature" tabindex="-1">Dynamics &amp; finite temperature <a class="header-anchor" href="#Dynamics-and-finite-temperature" aria-label="Permalink to &quot;Dynamics &amp; finite temperature {#Dynamics-and-finite-temperature}&quot;">​</a></h2><h3 id="DQPT-in-the-Ising-modeldynamics/0.ising-dqpt/index.md" tabindex="-1"><a href="./dynamics/0.ising-dqpt/">DQPT in the Ising model</a> <a class="header-anchor" href="#DQPT-in-the-Ising-modeldynamics/0.ising-dqpt/index.md" aria-label="Permalink to &quot;[DQPT in the Ising model](dynamics/0.ising-dqpt/index.md) {#DQPT-in-the-Ising-modeldynamics/0.ising-dqpt/index.md}&quot;">​</a></h3><p><img src="'+c+'" alt=""></p><p>Quenches the transverse-field Ising chain across its critical point and tracks the Loschmidt echo in search of non-analyticities (dynamical quantum phase transitions), on both a finite chain (<code>TDVP2</code>/<code>TDVP</code>) and directly in the thermodynamic limit (<code>changebonds</code> with <code>OptimalExpand</code>, then <code>TDVP</code>). A compact introduction to real-time evolution and environment reuse, still without symmetries. <strong>Level: introductory/intermediate.</strong></p><h3 id="Finite-temperature-XY-modeldynamics/1.xy-finiteT/index.md" tabindex="-1"><a href="./dynamics/1.xy-finiteT/">Finite temperature XY model</a> <a class="header-anchor" href="#Finite-temperature-XY-modeldynamics/1.xy-finiteT/index.md" aria-label="Permalink to &quot;[Finite temperature XY model](dynamics/1.xy-finiteT/index.md) {#Finite-temperature-XY-modeldynamics/1.xy-finiteT/index.md}&quot;">​</a></h3><p><img src="'+h+'" alt=""></p><p>Simulates the finite-temperature XY chain by purifying the infinite-temperature density matrix and evolving it in imaginary time, then compares the resulting partition function and free energy against exact diagonalization and, via BenchmarkFreeFermions.jl, the exact free-fermion solution. A technical, comparison-heavy example built around <code>MPSKit.infinite_temperature_density_matrix</code> and imaginary-time evolution rather than ground-state search. <strong>Level: advanced.</strong></p><h2 id="Statistical-mechanics" tabindex="-1">Statistical mechanics <a class="header-anchor" href="#Statistical-mechanics" aria-label="Permalink to &quot;Statistical mechanics {#Statistical-mechanics}&quot;">​</a></h2><h3 id="The-Hard-Hexagon-modelstatmech/0.hard-hexagon/index.md" tabindex="-1"><a href="./statmech/0.hard-hexagon/">The Hard Hexagon model</a> <a class="header-anchor" href="#The-Hard-Hexagon-modelstatmech/0.hard-hexagon/index.md" aria-label="Permalink to &quot;[The Hard Hexagon model](statmech/0.hard-hexagon/index.md) {#The-Hard-Hexagon-modelstatmech/0.hard-hexagon/index.md}&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>Extracts the central charge of the hard hexagon lattice gas by finding the leading boundary MPS of its transfer matrix with <code>VUMPS</code> (using Fibonacci-anyon virtual spaces), then fitting the CFT-predicted scaling relation between entanglement entropy and correlation length as the bond dimension is increased. The only classical statistical-mechanics example in the gallery, and the only one demonstrating non-abelian anyonic symmetries (<code>FibonacciAnyon</code>) in MPSKit. <strong>Level: advanced.</strong></p>',40)])])}const E=m(f,[["render",x]]);export{X as __pageData,E as default};
